---
struct btf_ext_info_sec {
        __u32   sec_name_off;
        __u32   num_info;
        /* Followed by num_info * record_size number of bytes */
        __u8    data[];
};

/* The minimum bpf_func_info checked by the loader */
struct bpf_func_info_min {
        __u32   insn_off;
        __u32   type_id;
};

